  void styleSwitch(Switch control){int[][] states={new int[]{android.R.attr.state_checked},new int[]{}};control.setThumbTintList(new ColorStateList(states,new int[]{purple,Color.rgb(145,145,151)}));control.setTrackTintList(new ColorStateList(states,new int[]{Color.rgb(91,70,122),Color.rgb(57,57,61)}));}
  @Override public void onBackPressed(){if(activeTab!=0)showTab(0);else super.onBackPressed();}
  void showTab(int tab){activeTab=tab;Drawable headerGlyph=getDrawable(getResources().getIdentifier(tab==3?"nav_back":"nav_account","drawable",getPackageName())).mutate();headerGlyph.setTint(ink);profileButton.setCompoundDrawablesWithIntrinsicBounds(headerGlyph,null,null,null);profileButton.setContentDescription(tab==3?"Back to Home":"Open settings");String[] titles={"","Apps","Timer","Settings"};pageTitle.setText(titles[tab]);pageTitle.setVisibility(tab==0?View.GONE:View.VISIBLE);heroGroup.setVisibility(tab==0?View.VISIBLE:View.GONE);focusDock.setVisibility(tab==0?View.VISIBLE:View.GONE);overviewCard.setVisibility(tab==0?View.VISIBLE:View.GONE);progressCard.setVisibility(tab==0?View.VISIBLE:View.GONE);historyCard.setVisibility(tab==0?View.VISIBLE:View.GONE);homeFocusCard.setVisibility(View.GONE);focusCard.setVisibility(tab==2?View.VISIBLE:View.GONE);appsLead.setVisibility(tab==1?View.VISIBLE:View.GONE);appsCard.setVisibility(tab==1?View.VISIBLE:View.GONE);goalCard.setVisibility(tab==1?View.VISIBLE:View.GONE);for(int i=0;i<root.getChildCount();i++){View child=root.getChildAt(i);if("schedule".equals(child.getTag()))child.setVisibility(tab==1?View.VISIBLE:View.GONE);if("settings".equals(child.getTag()))child.setVisibility(tab==3?View.VISIBLE:View.GONE);}accessibilityCard.setVisibility(tab==3?View.VISIBLE:View.GONE);accountCard.setVisibility(tab==3?View.VISIBLE:View.GONE);for(int i=0;i<bottomNav.getChildCount();i++){Button button=(Button)bottomNav.getChildAt(i);boolean selected=i==tab;int color=selected?purple:Color.rgb(138,138,146);button.setTextColor(color);button.setTypeface(null,selected?Typeface.BOLD:Typeface.NORMAL);Drawable glyph=button.getCompoundDrawables()[1];if(glyph!=null)glyph.setTint(color);button.setBackground(bg(Color.TRANSPARENT,0));}}
  String timeLabel(String part){int minute=prefs.getInt("work"+part,part.equals("start")?540:1020);return (part.equals("start")?"From ":"To ")+String.format(Locale.US,"%02d:%02d",minute/60,minute%60);}
  void editTime(String part,Button button){int value=prefs.getInt("work"+part,part.equals("start")?540:1020);new android.app.TimePickerDialog(this,(view,hour,minute)->{prefs.edit().putInt("work"+part,hour*60+minute).apply();button.setText(timeLabel(part));},value/60,value%60,false).show();}
  void changeDuration(int delta){int minutes=Math.max(5,Math.min(180,prefs.getInt("sessionMinutes",25)+delta));prefs.edit().putInt("sessionMinutes",minutes).apply();refresh();}
  void refresh(){if(summary==null)return;FocusLedger.settle(prefs,System.currentTimeMillis());focusMinutesView.setText(FocusLedger.minutesToday(prefs)+"m");streakView.setText(String.valueOf(FocusLedger.streak(prefs)));sessionsView.setText(String.valueOf(FocusLedger.completedToday(prefs)));pointsView.setText(String.valueOf(prefs.getInt("focusPoints",0)));int chosen=0;for(Map.Entry<String,?> item:prefs.getAll().entrySet())if(item.getKey().startsWith("d_")&&Boolean.TRUE.equals(item.getValue()))chosen++;distractionSummary.setText(chosen==0?"No apps selected":chosen==1?"1 distracting app":chosen+" distracting apps");renderSelectedIcons();accessibilityStatus.setText(accessibilityEnabled()?"App awareness is on. Reminders can appear when a selected app reaches a limit.":"App awareness is off. Enable it for distraction reminders.");long left=prefs.getLong("focusUntil",0)-System.currentTimeMillis();boolean hard=left>0&&prefs.getLong("hardModeUntil",0)>System.currentTimeMillis();focusStatus.setText(left>0?duration(left)+" remaining"+(hard?" · Hard Mode on":""):"Choose a duration and begin when you're ready.");timerFace.setText(left>0?String.format(java.util.Locale.US,"%02d:%02d",Math.max(0,left/60000),Math.max(0,(left/1000)%60)):String.format(java.util.Locale.US,"%02d:00",prefs.getInt("sessionMinutes",25)));digitalClock.setTimeText(timerFace.getText().toString());focusButton.setText(hard?"Hard Mode active":left>0?"End focus session":"Start focus session");homeFocusButton.setText(left>0?"Focus running · "+duration(left)+" left":"Open focus timer");quickFocus.setText(left>0?"Focus · "+duration(left)+" left":"Start to focus");focusButton.setEnabled(!hard);focusButton.setAlpha(hard?.55f:1f);summary.setTextSize(hasAccess()?48:24);hardMode.setEnabled(left<=0);settingsHardMode.setEnabled(left<=0);settingsHardMode.setChecked(prefs.getBoolean("hardModeEnabled",false));if(!hasAccess()){showGeode(0, false);summary.setText("Usage Access needed");status.setText("Allow access to see app time. Data stays on this device.");list.removeAllViews();topApps.removeAllViews();weekBars.removeAllViews();return;}
    Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);long start=c.getTimeInMillis();
    UsageStatsManager manager=(UsageStatsManager)getSystemService(USAGE_STATS_SERVICE);Map<String,UsageStats> data=manager.queryAndAggregateUsageStats(start,System.currentTimeMillis());ArrayList<UsageStats> rows=new ArrayList<>(data.values());Collections.sort(rows,(a,b)->Long.compare(b.getTotalTimeInForeground(),a.getTotalTimeInForeground()));
    long total=0,dist=0;topAppMax=0;list.removeAllViews();topApps.removeAllViews();int shown=0;for(UsageStats row:rows){long ms=row.getTotalTimeInForeground();if(!isTrackable(row.getPackageName()))continue;total+=ms;String key="d_"+row.getPackageName();if(prefs.getBoolean(key,false))dist+=ms;if(ms<60000)continue;if(shown++>=40)continue;
      String label=row.getPackageName();try{label=getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(label,0)).toString();}catch(Exception ignored){}
      final String app=row.getPackageName();final String appLabel=label;int appLimit=prefs.getInt("limit_"+app,0);
      LinearLayout item=row();item.setPadding(0,dp(8),0,dp(8));list.addView(item);ImageView appIcon=new ImageView(this);try{appIcon.setImageDrawable(getPackageManager().getApplicationIcon(app));}catch(Exception ignored){appIcon.setImageResource(android.R.drawable.sym_def_app_icon);}item.addView(appIcon,new LinearLayout.LayoutParams(dp(29),dp(29)));LinearLayout appInfo=new LinearLayout(this);appInfo.setOrientation(1);LinearLayout.LayoutParams appInfoSpace=new LinearLayout.LayoutParams(0,-2,1);appInfoSpace.setMargins(dp(9),0,dp(4),0);item.addView(appInfo,appInfoSpace);CheckBox box=new CheckBox(this);box.setText(label);box.setTextColor(ink);box.setTextSize(14);box.setButtonTintList(ColorStateList.valueOf(purple));box.setSingleLine(true);box.setEllipsize(android.text.TextUtils.TruncateAt.END);box.setChecked(prefs.getBoolean(key,false));appInfo.addView(box);TextView time=muted(duration(ms)+" today",12);time.setPadding(dp(32),0,0,0);appInfo.addView(time);box.setOnCheckedChangeListener((v,checked)->{prefs.edit().putBoolean(key,checked).apply();refresh();});
      Button limit=button(appLimit>0?duration(appLimit*60000L)+" limit":"Set limit");limit.setTextSize(12);item.addView(limit,new LinearLayout.LayoutParams(dp(92),dp(48)));limit.setOnClickListener(v->editAppLimit(app,appLabel));
      if(shown<=3)addTopApp(app,label,ms,prefs.getBoolean(key,false));}
    if(shown==0){topApps.addView(text("Your activity will appear after you use some apps.",13,false));list.addView(text("No app activity yet today.",13,false));}
    summary.setText(duration(total));status.setText(duration(dist)+" / "+duration(prefs.getInt("goal",120)*60000L));goalProgress.setProgress((int)Math.min(1000,dist*1000L/(prefs.getInt("goal",120)*60000L)));showGeode(dist, true);renderWeek(manager);
    if(cloud.signedIn()&&System.currentTimeMillis()-prefs.getLong("lastCloudSync",0)>15*60000)syncCloud(total,dist);
  }
  void showGeode(long distractionMs,boolean known){int stage=GeodeLevel.stage(distractionMs,prefs.getInt("goal",120),known);GeodeArt.show(this,geodeImage,stage);String label=GeodeLevel.label(stage,known);geodeCaption.setText(label);geodeImage.setContentDescription(label+". Based on distracting app time against your daily budget.");}
  void addTopApp(String packageName,String label,long ms,boolean distracting){
    if(topAppMax==0)topAppMax=Math.max(1,ms);
    LinearLayout item=row();item.setPadding(0,dp(13),0,dp(13));
    ImageView icon=new ImageView(this);try{icon.setImageDrawable(getPackageManager().getApplicationIcon(packageName));}catch(Exception ignored){icon.setImageResource(android.R.drawable.sym_def_app_icon);}item.addView(icon,new LinearLayout.LayoutParams(dp(38),dp(38)));
    LinearLayout names=new LinearLayout(this);names.setOrientation(1);LinearLayout.LayoutParams namesSpace=new LinearLayout.LayoutParams(0,-2,1);namesSpace.setMargins(dp(14),0,0,0);item.addView(names,namesSpace);
    LinearLayout heading=row();TextView name=text(label,16,false);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);heading.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView time=muted(duration(ms),14);heading.addView(time);names.addView(heading);
    ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgress((int)Math.min(1000,ms*1000L/topAppMax));bar.setProgressTintList(ColorStateList.valueOf(distracting?Color.rgb(215,146,172):purple));bar.setProgressBackgroundTintList(ColorStateList.valueOf(Color.rgb(40,40,43)));bar.setContentDescription(label+", "+duration(ms)+". Bar relative to most used app.");LinearLayout.LayoutParams barSpace=new LinearLayout.LayoutParams(-1,dp(5));barSpace.topMargin=dp(10);names.addView(bar,barSpace);topApps.addView(item);
  }
  void renderWeek(UsageStatsManager manager){weekBars.removeAllViews();long[] values=new long[7];Calendar day=Calendar.getInstance();day.set(Calendar.HOUR_OF_DAY,0);day.set(Calendar.MINUTE,0);day.set(Calendar.SECOND,0);day.set(Calendar.MILLISECOND,0);day.add(Calendar.DAY_OF_YEAR,-6);String[] labels=new String[7];for(int i=0;i<7;i++){long start=day.getTimeInMillis();labels[i]=new SimpleDateFormat("EE",Locale.US).format(day.getTime());day.add(Calendar.DAY_OF_YEAR,1);long end=i==6?System.currentTimeMillis():day.getTimeInMillis();Map<String,UsageStats> rows=manager.queryAndAggregateUsageStats(start,end);if(rows!=null)for(UsageStats row:rows.values())if(isTrackable(row.getPackageName()))values[i]+=Math.max(0,row.getTotalTimeInForeground());}long max=60000;for(long value:values)max=Math.max(max,value);for(int i=0;i<7;i++){LinearLayout column=new LinearLayout(this);column.setOrientation(1);column.setGravity(android.view.Gravity.BOTTOM|android.view.Gravity.CENTER_HORIZONTAL);weekBars.addView(column,new LinearLayout.LayoutParams(0,-1,1));View bar=new View(this);bar.setBackground(bg(i==6?purple:Color.rgb(181,175,222),5));int height=(int)Math.max(dp(3),values[i]*dp(72)/max);column.addView(bar,new LinearLayout.LayoutParams(dp(25),height));TextView dayLabel=text(labels[i],11,false);dayLabel.setGravity(android.view.Gravity.CENTER);column.addView(dayLabel,new LinearLayout.LayoutParams(-1,dp(24)));column.setContentDescription(labels[i]+": "+duration(values[i]));}}
  void editAppLimit(String app,String label){EditText input=new EditText(this);input.setInputType(2);input.setSingleLine(true);input.setHint("Minutes per day");int current=prefs.getInt("limit_"+app,0);if(current>0)input.setText(String.valueOf(current));LinearLayout container=new LinearLayout(this);container.setPadding(dp(24),0,dp(24),0);container.addView(input,new LinearLayout.LayoutParams(-1,-2));android.app.AlertDialog.Builder dialog=new android.app.AlertDialog.Builder(this).setTitle("Daily limit for "+label).setView(container).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{try{int value=Integer.parseInt(input.getText().toString());if(value<1||value>1440)throw new Exception();prefs.edit().putInt("limit_"+app,value).apply();refresh();}catch(Exception ex){Toast.makeText(this,"Enter 1–1440 minutes",Toast.LENGTH_SHORT).show();}});if(current>0)dialog.setNeutralButton("Remove limit",(d,w)->{prefs.edit().remove("limit_"+app).apply();refresh();});dialog.show();}
  void refreshAndSync(){if(!hasAccess()){cloudStatus.setText("Allow Usage Access before syncing.");return;}prefs.edit().putLong("lastCloudSync",0).apply();refresh();}
  void refreshAccountActions(){if(signInForm!=null)signInForm.setVisibility(cloud.signedIn()?View.GONE:View.VISIBLE);if(syncActions!=null)syncActions.setVisibility(cloud.signedIn()?View.VISIBLE:View.GONE);}
  void signIn(String email,EditText passwordField,boolean create){if(syncing)return;String password=passwordField.getText().toString();syncing=true;cloudStatus.setText(create?"Creating account…":"Signing in…");new Thread(()->{try{cloud.signIn(email,password,create);runOnUiThread(()->{passwordField.setText("");syncing=false;cloudStatus.setText("Signed in. Syncing today…");refreshAccountActions();refreshAndSync();});}catch(Exception ex){runOnUiThread(()->{syncing=false;cloudStatus.setText("Sign-in failed: "+ex.getMessage());});}}).start();}
  void syncCloud(long total,long distraction){if(syncing)return;syncing=true;cloudStatus.setText("Syncing today…");String date=new SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US).format(new Date());new Thread(()->{try{JSONArray days=cloud.sync(date,total,distraction);StringBuilder result=new StringBuilder("Synced today · ").append(cloud.settingsMessage()).append("\n");Map<String,Long> totals=new LinkedHashMap<>();for(int i=0;i<days.length();i++){JSONObject day=days.getJSONObject(i);String source=day.optString("source");totals.put(source,totals.getOrDefault(source,0L)+day.optLong("activeMs"));}for(Map.Entry<String,Long> entry:totals.entrySet()){String source=entry.getKey();result.append(source.equals("chrome")?"Chrome websites":source.equals("windows")?"Windows apps":"Android apps").append(": ").append(duration(entry.getValue())).append("\n");}prefs.edit().putLong("lastCloudSync",System.currentTimeMillis()).apply();runOnUiThread(()->{syncing=false;cloudStatus.setText(result.toString().trim());refresh();});}catch(Exception ex){runOnUiThread(()->{syncing=false;cloudStatus.setText("Sync failed: "+ex.getMessage());});}}).start();}
